import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"Prod deployment validator — scripts/validate-prod.mjs","description":"","frontmatter":{},"headers":[],"relativePath":"ops/prod-validator.md","filePath":"ops/prod-validator.md"}'),r={name:"ops/prod-validator.md"};function i(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="prod-deployment-validator-—-scripts-validate-prod-mjs" tabindex="-1">Prod deployment validator — <code>scripts/validate-prod.mjs</code> <a class="header-anchor" href="#prod-deployment-validator-—-scripts-validate-prod-mjs" aria-label="Permalink to &quot;Prod deployment validator — `scripts/validate-prod.mjs`&quot;">​</a></h1><p><strong>Status 2026-11-04:</strong> reference/runbook, live and still accurate in structure. Tool and both workflows exist (<code>scripts/validate-prod.mjs</code>, <code>.github/workflows/validate-prod.yml</code>, <code>deploy-prod.yml</code>). Doc drift: the schedule is no longer every 6 h; <code>validate-prod.yml</code> now runs on deploy-prod completion (<code>workflow_run</code>, line 22) plus a daily cron <code>0 6 * * *</code> (line 31), changed in <code>6aa2d113449</code>. The env.js no-cache check exists as a WARN (<code>scripts/validate-prod.mjs:254-270</code>). Not verified (no remote access): whether the Tailscale/CF DNS gotcha still applies.</p><p><code>npm run validate-prod</code> — a detailed, repeatable, browser-based validator for a live Orrery deployment. Elevated from the ad-hoc post-deploy spot-checks used to verify the 2026-07-22 prod fixes; those one-off Playwright snippets are now a tracked tool with structured pass/fail output, a machine-readable report, and a non-zero exit on failure.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to &quot;Run it&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-prod</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # → https://www.orrerylearn.com</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VALIDATE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://127.0.0.1:4173</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-prod</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # local vite preview</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VALIDATE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">staging</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-prod</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # any target</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VALIDATE_JSON</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tmp/report.json</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-prod</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # + machine report</span></span></code></pre></div><p>Exit code: <strong>0</strong> when every non-warn check passes, <strong>1</strong> on any FAIL. WARN checks (environment-conditional — e.g. error-monitoring off on a DSN-less build) are surfaced but never fail the run.</p><h2 id="why-a-real-browser-not-curl" tabindex="-1">Why a real browser (not curl) <a class="header-anchor" href="#why-a-real-browser-not-curl" aria-label="Permalink to &quot;Why a real browser (not curl)&quot;">​</a></h2><p>The load-bearing checks only exist in a page context: console/page errors, CSP <strong>violations</strong>, the service-worker navigate-fallback, locale-switch <strong>rendered content</strong> (not just the URL), and a <strong>real error POSTing</strong> to the telemetry edge. A curl/header check would have passed while the site was actually broken — which is exactly how three of the 2026-07-22 bugs hid (edge/CORS tests green, page context broken).</p><h2 id="what-it-asserts-8-suites-60-checks" tabindex="-1">What it asserts (8 suites, ~60 checks) <a class="header-anchor" href="#what-it-asserts-8-suites-60-checks" aria-label="Permalink to &quot;What it asserts (8 suites, ~60 checks)&quot;">​</a></h2><ol><li><strong>headers</strong> — reachable; HSTS / X-Content-Type-Options / X-Frame-Options / Referrer-Policy / CSP present; and the exact CSP directives the fixes need (<code>frame-src</code> youtube, <code>connect-src</code> telemetry.orrerylearn.com, <code>media-src</code>).</li><li><strong>pwa</strong> — <code>/sw.js</code> served; <strong><code>navigateFallback = /404.html</code></strong> (not home); <code>/_app/env.js</code> served.</li><li><strong>routes</strong> — every top-level route (mirrors <code>svelte.config.js</code> SEED_ROUTES) → 2xx, no page errors, no unexpected 4xx.</li><li><strong>deep-routes</strong> — <code>/programs/&lt;id&gt;</code>, a <code>/science/&lt;tab&gt;/&lt;section&gt;</code>, <code>?id=</code> and <code>?site=</code> query routes.</li><li><strong>i18n-full</strong> — <strong>every top-level route × all 13 non-base locales</strong> (325 checks): each serves 2xx AND the served <code>&lt;html lang=&quot;xx&quot;&gt;</code> matches the locale. A home-fallback (the PWA-shell / prerender failure mode) shows <code>lang=&quot;en-US&quot;</code> and fails. fetch-based + parallel (concurrency 12) so it stays fast; rolled up to one result per locale (<code>locale de (25/25 routes)</code>), failures listed inline.</li><li><strong>data</strong> — <code>/data/i18n/*.json</code> bundles served (the VPS <code>/data</code>-overlay seed).</li><li><strong>regression-guards</strong> — one guard per prod bug fixed 2026-07-22, so they can&#39;t silently return: <ul><li>programs page renders real content (VPS <code>/data</code> overlay).</li><li>gallery video mounts a YouTube iframe (CSP <code>frame-src</code>).</li><li>locale switch stays on the route with its content (PWA neutral shell).</li><li>error monitoring: DSN valid + connect allowed + a <strong>real error POSTs 200</strong> to GlitchTip project 4 (CSP <code>connect-src</code> + the dashless-key DSN).</li><li><code>/moon</code> fires <strong>no</strong> route-patches 404 (the <code>has_route_patches</code> fetch gate).</li></ul></li><li><strong>interactions</strong> — mobile home+nav, mobile <code>/explore</code> 3D canvas, missions <code>?q=</code> search filters.</li></ol><h2 id="extending" tabindex="-1">Extending <a class="header-anchor" href="#extending" aria-label="Permalink to &quot;Extending&quot;">​</a></h2><p>Add a <code>record(name, ok, detail, {warn})</code> call inside the relevant <code>suite(...)</code> block. Keep the route inventory (<code>TOP_ROUTES</code>) in sync with <code>svelte.config.js</code> SEED_ROUTES when routes are added. Every new prod-fix should land its own regression guard here in the same change.</p><h2 id="relationship-to-the-other-gates" tabindex="-1">Relationship to the other gates <a class="header-anchor" href="#relationship-to-the-other-gates" aria-label="Permalink to &quot;Relationship to the other gates&quot;">​</a></h2><ul><li><code>npm run preflight</code> / CI — typecheck/lint/unit/build; never touches a live URL.</li><li><code>docker-e2e</code> — Playwright against a <code>vite preview</code> of the built bundle (localhost), on amd64 software-GL; the pre-merge correctness gate.</li><li><strong><code>validate-prod</code></strong> — the only gate that exercises the <strong>live deployment</strong> end to end (VPS serving layer: nginx CSP + headers, the <code>/data</code> overlay, the service worker, real telemetry). Run it <strong>after every prod deploy</strong>.</li></ul><h2 id="automated-runs-wired-2026-07-22-schedule-since-changed-to-deploy-completion-daily-cron-06-00-utc-in-6aa2d113449" tabindex="-1">Automated runs (wired 2026-07-22; schedule since changed to deploy-completion + daily cron 06:00 UTC in <code>6aa2d113449</code>) <a class="header-anchor" href="#automated-runs-wired-2026-07-22-schedule-since-changed-to-deploy-completion-daily-cron-06-00-utc-in-6aa2d113449" aria-label="Permalink to &quot;Automated runs (wired 2026-07-22; schedule since changed to deploy-completion + daily cron 06:00 UTC in `6aa2d113449`)&quot;">​</a></h2><ul><li><strong>Post-deploy</strong> — a <code>validate</code> job in <code>.github/workflows/deploy-prod.yml</code> (<code>needs: deploy</code>, skipped when the deploy itself no-op&#39;d) runs it against the public URL from a GH runner right after each deploy. A red job = &quot;deployed but the public site is broken.&quot;</li><li><strong>Scheduled</strong> — <code>.github/workflows/validate-prod.yml</code> runs it <s>every 6 h (<code>cron: 0 */6 * * *</code>)</s> (now daily, see above) + <code>workflow_dispatch</code>, as a synthetic correctness monitor (deeper than an UptimeRobot ping, coarser cadence). Catches edge/cert/ data-overlay/telemetry drift a green deploy can&#39;t.</li><li>Both use <code>vars.PROD_PUBLIC_URL</code> (fallback <code>https://www.orrerylearn.com</code>) and <strong>omit <code>VALIDATE_ERROR_POST</code></strong>, so the error-monitoring guard does config-only checks (DSN baked + dashless key + CSP connect) and never fires a synthetic event into GlitchTip project 4.</li></ul><h2 id="gotcha-—-run-it-off-the-tailnet" tabindex="-1">Gotcha — run it OFF the tailnet <a class="header-anchor" href="#gotcha-—-run-it-off-the-tailnet" aria-label="Permalink to &quot;Gotcha — run it OFF the tailnet&quot;">​</a></h2><p>The origin firewalls <strong>:443 to Cloudflare IPs only</strong>; the public domain resolves to CF anycast. But a laptop on <strong>Tailscale</strong> gets the origin IP from MagicDNS and hits :443 directly (non-CF) → every request times out and the whole run reds with <code>HTTP -1</code> / <code>page.goto: Timeout</code>. This is a local DNS artifact, <strong>not</strong> an outage — confirm with <code>dig +short @1.1.1.1 www.orrerylearn.com</code> (CF IPs) + <code>curl --resolve www.orrerylearn.com:443:&lt;cf-ip&gt; https://www.orrerylearn.com/</code> (→ 200). The CI runners are off-tailnet, so the automated jobs see CF and pass; only local-from-tailnet runs are affected (exclude the domain from MagicDNS, or run it elsewhere).</p>',18)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
